#!/bin/sh
##
## Regenerates the protocol buffer code from expl.proto.
## See doc/devel/protoc.txt for the version policy.
##
##   sh generate.sh          C++ code (expl.pb.cc, expl.pb.h) in this directory.
##                           protoc must be the same version as the libprotobuf
##                           that PRISM is linked against (USE_PB=1).
##   sh generate.sh python   Python code (expl_pb2.py, expl_pb2.pyi) in bin/tprism/.
##                           protoc must be 3.21.12 (protoc release v21.12), so that
##                           the code works with protobuf >= 4.21.12 at runtime.
##
## The protoc command can be given by the PROTOC environment variable
## (default: protoc).
##
cd `dirname $0`
PROTOC=${PROTOC:-protoc}

case "$1" in
    python)
        version=`$PROTOC --version`
        if [ "$version" != "libprotoc 3.21.12" ]; then
            echo "`basename $0`: the Python code must be generated by protoc 3.21.12 (found: $version)" 1>&2
            exit 1
        fi
        $PROTOC --python_out=../../../bin/tprism --pyi_out=../../../bin/tprism expl.proto
        ;;
    "")
        $PROTOC --cpp_out=. expl.proto
        ;;
    *)
        echo "usage: `basename $0` [python]" 1>&2
        exit 1
        ;;
esac
